using CrochetCraft.Data;using CrochetCraft.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace CrochetCraft.Controllers;
public class OrdersController(AppDbContext db):Controller {
 public async Task<IActionResult> Checkout(int id){var uid=HttpContext.Session.GetInt32("UserId");if(uid==null)return RedirectToAction("Login","Account");var d=await db.Designs.Include(x=>x.Product).FirstOrDefaultAsync(x=>x.Id==id&&x.UserId==uid);if(d==null)return NotFound();if(await db.Orders.AnyAsync(x=>x.DesignId==id))return RedirectToAction("Mine");ViewBag.Design=d;return View(new CheckoutVm{DesignId=id});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Checkout(CheckoutVm vm){var uid=HttpContext.Session.GetInt32("UserId");if(uid==null)return RedirectToAction("Login","Account");var d=await db.Designs.Include(x=>x.Product).FirstOrDefaultAsync(x=>x.Id==vm.DesignId&&x.UserId==uid);if(d==null)return NotFound();if(await db.Orders.AnyAsync(x=>x.DesignId==d.Id))return RedirectToAction("Mine");if(!ModelState.IsValid){ViewBag.Design=d;return View(vm);}db.Orders.Add(new CraftOrder{UserId=uid.Value,DesignId=d.Id,ShippingAddress=vm.ShippingAddress.Trim(),Phone=vm.Phone,Total=d.UnitPrice*d.Quantity});await db.SaveChangesAsync();TempData["Message"]="Your custom crochet order has been placed!";return RedirectToAction("Mine");}
 public async Task<IActionResult> Mine(){var uid=HttpContext.Session.GetInt32("UserId");if(uid==null)return RedirectToAction("Login","Account");return View(await db.Orders.Include(x=>x.Design).ThenInclude(x=>x!.Product).Where(x=>x.UserId==uid).OrderByDescending(x=>x.Id).ToListAsync());}
}